import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import PostUser from 'flarum/forum/components/PostUser';
import UserCard from 'flarum/forum/components/UserCard';
import UserHandle from './components/UserHandle';
app.initializers.add('huoxin-user-handles', () => {
  extend(PostUser.prototype, 'linkChildren', function (items, user) {
    const showOnPost = app.forum.attribute('userHandlesShowOnPost') ?? true;
    if (!showOnPost) return;
    items.add('user-handle', m(UserHandle, {
      user: user,
      className: "PostUser-handle"
    }), 75);
  });
  extend(UserCard.prototype, 'contentItems', function (items) {
    const showOnCard = app.forum.attribute('userHandlesShowOnCard') ?? true;
    if (!showOnCard) return;
    const user = this.attrs.user;
    if (!user) return;
    const identityNode = items.get('identity');
    if (!identityNode) return;
    const handleNode = m(UserHandle, {
      user: user,
      className: "UserCard-handle"
    });
    if (!Array.isArray(identityNode.children)) {
      identityNode.children = identityNode.children ? [identityNode.children] : [];
    }
    identityNode.children.push(handleNode);
  });
});